# shellcheck shell=sh
# Generates the environment file (POSIX sh, sourced by bin/om818 after lib/common.sh).
#
# The environment is generated once (on install, update and config change) rather than computed
# at each shell start: detecting tools and reading the config would slow every shell down, and
# the config may use arrays that sh can't read. The result is plain POSIX sh, sourced by the
# startup files (lib/startup-files.sh) and om818.plugin.bash; it sources the user's env.d/ files
# at its end.

# Write the environment file (atomically: shells may be sourcing it). Not called in a condition:
# errexit then stops at the first failing command, e.g. an integration's (inside an `if`, sh would
# ignore errexit in the whole function); bin/om818's exit trap removes the partial file
env_generate() {
  local tmp
  mkdir -p -- "$OM818_STATE_DIR"
  tmp="${OM818_ENV}.tmp.$$"
  # shellcheck disable=SC2034 # read by on_exit (lib/common.sh)
  _OM818_EXIT_TMP="$tmp"
  _OM818_ENV_WRITE=1 env_render >"$tmp"
  mv -f -- "$tmp" "$OM818_ENV"
  # shellcheck disable=SC2034 # read by on_exit (lib/common.sh)
  _OM818_EXIT_TMP=''
}

# Print the environment file
env_render() {
  local name out entry first='' list='' body='' vars='' dir
  printf '# Generated by om818 %s: do not edit (regenerate it: om818 env).\n' "$(version)"
  printf '# Your own variables go in %s/*.sh.\n\n' "$OM818_ENV_D"
  env_helpers
  # (not in a temporary install: the host's own oh-my-818 put them, for the host's tools)
  if [ -z "${OM818_TEMP:-}" ]; then
    printf '\n# PATH as the previous environment left it: a folder it added that is no longer set\n'
    printf '# (a setting turned off) is taken out after your variables\n'
    printf 'om818_path_reset\n'
  fi

  for name in $(integration_names); do
    out="$(env_integration "$name")"
    entry="${out%%"
"*}"
    if [ "$entry" = "$out" ]; then out=''; else out="${out#*"
"}"; fi
    if [ -n "$out" ]; then
      body="${body}
# ${name}
${out}
"
      vars="${vars} $(printf '%s\n' "$out" |
        sed -n 's/.*export \([A-Za-z_][A-Za-z0-9_]*\)=.*/\1/p')"
    fi
    if [ -z "$entry" ]; then continue; fi
    if [ "$name" = 'mise' ]; then first="$entry"; else list="${list:+${list} }${entry}"; fi
  done

  # (each name on its own: sed's lines joined by spaces)
  set -f
  # shellcheck disable=SC2086 # split on purpose
  set -- $vars
  set +f
  # (not in a temporary install: the host's own oh-my-818 set them, for the host's tools)
  if [ -z "${OM818_TEMP:-}" ]; then
    printf '\n# Variables an earlier environment exported, not set here (a setting turned off, a\n'
    printf '# tool gone): new terminals inherit them from the login session, so they go\n'
    printf 'om818_env_unset '
    quote "$*"
  fi
  printf "_om818_vars=''\n"
  printf '%s' "$body"
  # shellcheck disable=SC2016 # written as is
  printf 'export OM818_ENV_VARS="${_om818_vars# }"\n'
  printf 'unset _om818_vars\n'

  printf '\n# Integrations for interactive shells (name:tool), mise first (it changes PATH, where\n'
  printf '# the others look for their tool): their setting and checks are done, shells only look\n'
  printf '# for the tool, since tools come and go (e.g. with mise)\n'
  printf 'om818_integrations='
  quote "${first}${first:+${list:+ }}${list}"

  # After the integrations: ~/.local/bin, where people put their own commands, comes before
  # mise's shims and Homebrew's
  printf '\n# User-specific executables (XDG, then the older ~/bin: Fedora'"'"'s profiles add\n'
  printf '# both), then oh-my-818'"'"'s command\n'
  env_path_prepend_if_dir "${HOME}/bin"
  env_path_prepend_if_dir "${HOME}/.local/bin"
  # (at the default location, spelled from HOME, as the startup files' lines: the same file
  # whatever regenerates it, zsh, whose OM818_DIR has its links resolved, or om818 env)
  dir="${XDG_DATA_HOME:-${HOME}/.local/share}/om818"
  if ! same_dir "$OM818_DIR" "$dir"; then dir="$OM818_DIR"; fi
  env_path_append "${dir}/bin"
  printf 'export PATH OM818_PATH_FRONT OM818_PATH_ADDED\n'

  # (read from ~/.zshenv, before the system's zshrc)
  printf "\n# zsh: Ubuntu's /etc/zsh/zshrc runs compinit, which oh-my-818 runs itself\n"
  printf 'skip_global_compinit=1\n'

  printf '\n# Your variables\n'
  printf '_om818_source_dir '
  quote "$OM818_ENV_D"
  if [ -z "${OM818_TEMP:-}" ]; then printf 'om818_path_prune\n'; fi
  env_sandbox_only
}

# Commands only for sandboxes (om818_sandbox_only): a folder of wrappers, first on PATH after
# everything else (~/.local/bin, env.d/), so that any program finding them on PATH gets the
# wrapper. Each one runs the real command (the next on PATH) inside a sandbox, else stops. Written
# by env_generate only (_OM818_ENV_WRITE=1): `om818 status` renders the environment to compare it
env_sandbox_only() {
  local dir="${OM818_STATE_DIR}/sandbox-only" cmd sandbox test='' tests='' names='' new
  # shellcheck disable=SC2154 # set by config_load
  if [ -z "$om818_sandbox_only" ]; then
    if [ -n "${_OM818_ENV_WRITE:-}" ]; then rm -rf -- "$dir"; fi
    return 0
  fi
  # shellcheck disable=SC2154,SC2016 # tests written into the wrappers
  for sandbox in $om818_sandboxes; do
    case "$sandbox" in
    drop) test='[ -n "${DROP_ENV:-}" ] || [ "${debian_chroot:-}" = drop ]' ;;
    # (toolbox and distrobox share the home folder: not counted unless listed themselves)
    container)
      test='{ [ -f /.dockerenv ] || [ -f /run/.containerenv ] || [ -n "${container:-}" ]; }'
      test="${test} && [ ! -f /run/.toolboxenv ] && [ -z \"\${CONTAINER_ID:-}\" ]"
      ;;
    toolbox) test='[ -f /run/.toolboxenv ]' ;;
    distrobox) test='[ -n "${CONTAINER_ID:-}" ]' ;;
    chroot) test='[ -n "${debian_chroot:-}" ]' ;;
    flatpak) test='[ -n "${FLATPAK_ID:-}" ]' ;;
    *) continue ;;
    esac
    tests="${tests:+${tests} || }{ ${test}; }"
    names="${names:+${names}, }${sandbox}"
  done
  # Written beside, then swapped in: the commands stay wrapped meanwhile, but for an instant
  if [ -n "${_OM818_ENV_WRITE:-}" ]; then
    new="${dir}.new.$$"
    rm -rf -- "$new"
    mkdir -p -- "$new"
    for cmd in $om818_sandbox_only; do
      case "$cmd" in '' | . | .. | */* | *[!A-Za-z0-9._+-]*) continue ;; esac
      env_sandbox_wrapper "$cmd" "$dir" "${tests:-false}" "${names:-none}" >"${new}/${cmd}"
      chmod +x -- "${new}/${cmd}"
    done
    rm -rf -- "$dir"
    mv -- "$new" "$dir"
  fi
  printf '\n# Commands only for sandboxes (om818_sandbox_only)\n'
  printf 'om818_path_first '
  quote "$dir"
}

# Print a wrapper of om818_sandbox_only
# usage: env_sandbox_wrapper <command> <its folder> <sandbox tests> <sandbox names>
env_sandbox_wrapper() {
  cat <<EOF
#!/bin/sh
# Generated by om818 env (om818_sandbox_only): ${1} runs only inside a sandbox (${4})
# The real one: the next on PATH, past this folder (also when PATH names it another way) and any
# other copy of it (e.g. another home's, mounted in a sandbox): they would run each other
real=''
IFS=:
set -f
for dir in \$PATH; do
  case "\$dir" in
  */om818/sandbox-only | */om818/sandbox-only/ | */om818/sandbox-only/.) continue ;;
  esac
  if [ "\$dir" != $(quote "$2") ] && [ -f "\$dir/${1}" ] && [ -x "\$dir/${1}" ] &&
    ! [ "\$dir/${1}" -ef "\$0" ]; then
    real="\$dir/${1}"
    break
  fi
done
unset IFS
set +f
if [ -z "\$real" ]; then
  printf '%s\\n' '${1}: command not found' >&2
  exit 127
fi
if [ "\${OM818_SANDBOX_ONLY:-}" != off ] && ! { ${3}; }; then
  printf '%s\\n' '${1}: not in a sandbox (${4}): run it in one,' \\
    'or anyway: OM818_SANDBOX_ONLY=off ${1}' >&2
  exit 126
fi
exec "\$real" "\$@"
EOF
}

# Print an integration's entry for the interactive shells (name:tool, empty when it is off or has
# no interactive part), then its environment lines. Its tool may be missing: the shells look
# for it at each start
env_integration() {
  integration_eval "$1"
  # Only those with an interactive part (an unmatched glob stays as is)
  set -- "$1" "${OM818_DIR}/integrations/${1}"/interactive.*
  # shellcheck disable=SC2154 # set by the integration's file
  if [ -e "$2" ] && { [ "$_OM818_I_STATE" = 'on' ] || [ "$_OM818_I_NO_TOOL" -eq 1 ]; }; then
    printf '%s:%s\n' "$1" "$om818_integration_tool"
  else
    printf '\n'
  fi
  if [ "$_OM818_I_STATE" = 'on' ] && command -v om818_integration_env >/dev/null 2>&1; then
    om818_integration_env
  fi
}

# The PATH functions, defined in every shell that sources the file: the user's env.d/ and shell.d/
# files use them too
env_helpers() {
  cat <<'EOF'
# Remove a directory from PATH
om818_path_remove() {
  case ":${PATH}:" in *":${1}:"*) ;; *) return 0 ;; esac
  _om818_path=''
  _om818_rest="${PATH}:"
  while [ -n "$_om818_rest" ]; do
    _om818_dir="${_om818_rest%%:*}"
    _om818_rest="${_om818_rest#*:}"
    if [ -n "$_om818_dir" ] && [ "$_om818_dir" != "$1" ]; then
      _om818_path="${_om818_path:+${_om818_path}:}${_om818_dir}"
    fi
  done
  PATH="$_om818_path"
  unset _om818_path _om818_rest _om818_dir
}
# Add a directory in front of PATH, unless it is already there (anywhere). It is also kept in
# OM818_PATH_FRONT, in order: on macOS, login shells put them back in front, where path_helper
# moved them. OM818_PATH_ADDED: those this environment (or the previous one) added itself
om818_path_prepend() {
  case ":${PATH}:" in
  *":${1}:"*)
    case ":${_om818_added_old:-}:" in
    *":${1}:"*) om818_path_added "$1" ;;
    esac
    ;;
  *)
    PATH="${1}${PATH:+:${PATH}}"
    om818_path_added "$1"
    ;;
  esac
  case ":${OM818_PATH_FRONT:-}:" in
  *":${1}:"*) ;;
  *) OM818_PATH_FRONT="${OM818_PATH_FRONT:+${OM818_PATH_FRONT}:}${1}" ;;
  esac
}
om818_path_added() {
  case ":${OM818_PATH_ADDED:-}:" in
  *":${1}:"*) ;;
  *) OM818_PATH_ADDED="${OM818_PATH_ADDED:+${OM818_PATH_ADDED}:}${1}" ;;
  esac
}
# Start new lists, keeping the previous ones: the directories already on PATH stay where they are
# (e.g. behind a virtualenv a child shell inherits); at the end (om818_path_prune), those the
# previous environment added and this one no longer sets are taken out
om818_path_reset() {
  _om818_added_old="${OM818_PATH_ADDED:-}"
  OM818_PATH_FRONT='' OM818_PATH_ADDED=''
}
# (a directory that was on PATH before, from the system or the profile, stays)
om818_path_prune() {
  _om818_front="${_om818_added_old:-}:"
  while [ -n "$_om818_front" ]; do
    _om818_d="${_om818_front%%:*}"
    _om818_front="${_om818_front#*:}"
    case ":${OM818_PATH_FRONT:-}:" in
    *":${_om818_d}:"*) ;;
    *) if [ -n "$_om818_d" ]; then om818_path_remove "$_om818_d"; fi ;;
    esac
  done
  unset _om818_front _om818_d _om818_added_old
}
# Add a directory at the end of PATH, unless it is already there
om818_path_append() {
  case ":${PATH}:" in *":${1}:"*) ;; *) PATH="${PATH:+${PATH}:}${1}" ;; esac
}
# Put a directory first on PATH, and keep it first: the zsh and bash modules take the directories
# of OM818_PATH_FIRST out before their integrations and put them back after (mise puts its tools
# in front of the PATH it is activated with), and before each prompt when something went in front
# (e.g. direnv, a virtualenv)
om818_path_first() {
  om818_path_remove "$1"
  PATH="${1}${PATH:+:${PATH}}"
  case ":${OM818_PATH_FIRST:-}:" in
  *":${1}:"*) ;;
  *) OM818_PATH_FIRST="${OM818_PATH_FIRST:+${OM818_PATH_FIRST}:}${1}" ;;
  esac
}
# Unset the variables of OM818_ENV_VARS (those the previous environment set) that aren't in the
# given list (those this one may set), both space-separated (no word splitting: zsh reads this
# file too)
om818_env_unset() {
  _om818_rest="${OM818_ENV_VARS:-} "
  while [ -n "${_om818_rest# }" ]; do
    _om818_var="${_om818_rest%% *}"
    _om818_rest="${_om818_rest#* }"
    case "$_om818_var" in '' | *[!A-Za-z0-9_]* | [0-9]*) continue ;; esac
    case " ${1} " in *" ${_om818_var} "*) ;; *) unset "$_om818_var" ;; esac
  done
  unset _om818_rest _om818_var
}
# Source the *.sh files of a directory, in name order (zsh: as sh, without failing when there are
# none)
_om818_source_dir() {
  if [ -n "${ZSH_VERSION:-}" ]; then emulate -L sh; fi
  # (bash's failglob, some users' option, would make an empty folder an error)
  _om818_fg=''
  if [ -n "${BASH_VERSION:-}" ] && shopt -q failglob 2>/dev/null; then
    _om818_fg=1
    shopt -u failglob
  fi
  for _om818_file in "$1"/*.sh; do
    if [ -r "$_om818_file" ]; then . "$_om818_file"; fi
  done
  if [ -n "$_om818_fg" ]; then shopt -s failglob; fi
  unset _om818_file _om818_fg
}
EOF
}

### Helpers for integrations (om818_integration_env functions)

# (each variable set is added to _om818_vars: the next environment unsets those it no longer sets)
# shellcheck disable=SC2016 # written as is
env_set() {
  local q
  q="$(quote "$2")"
  printf 'export %s=%s; _om818_vars="${_om818_vars} %s"\n' "$1" "$q" "$1"
}

# A default: a value the user set before (e.g. GOPATH in ~/.profile) wins, and is theirs: never
# unset by a later environment
# shellcheck disable=SC2016 # written as is
env_set_default() {
  local q
  q="$(quote "$2")"
  printf 'if [ -z "${%s:-}" ] || [ "$%s" = %s ]; then\n' "$1" "$1" "$q"
  printf '  export %s=%s; _om818_vars="${_om818_vars} %s"\nfi\n' "$1" "$q" "$1"
}

env_path_prepend() {
  printf 'om818_path_prepend '
  quote "$1"
}

env_path_prepend_if_dir() {
  local q
  q="$(quote "$1")"
  printf 'if [ -d %s ]; then om818_path_prepend %s; fi\n' "$q" "$q"
}

env_path_append() {
  printf 'om818_path_append '
  quote "$1"
}
